#!/usr/bin/env bash
# P1M GCP WG read-only status and aggregate health evidence.
# Run ONLY on an authorized GCP VM session. NEVER reads wg0.conf/private keys.
# No changes to systemctl, iptables, sysctl, routes, services, DNS or firewall.
# No domain lookup or outbound packet generated by this script.
set -u

emit(){ printf 'P1M_GCP_%s=%s\n' "$1" "$2"; }
unit_state(){
    local output
    output="$(systemctl is-active "$1" 2>/dev/null)" || true
    case "$output" in
        active|inactive|failed|activating|deactivating) emit "$2" "$output";;
        *) emit "$2" "UNAVAILABLE";;
    esac
}
has(){ command -v "$1" >/dev/null 2>&1; }
wg_read(){
    # Optional non-interactive read-only access. sudo -n never prompts.
    if wg show wg0 listen-port >/dev/null 2>&1;then
        wg show wg0 "$1" 2>/dev/null
    elif has sudo && sudo -n wg show wg0 listen-port >/dev/null 2>&1;then
        sudo -n wg show wg0 "$1" 2>/dev/null
    else
        return 1
    fi
}
iptables_read(){
    if iptables "$@" >/dev/null 2>&1;then
        iptables "$@" 2>/dev/null
    elif has sudo && sudo -n iptables "$@" >/dev/null 2>&1;then
        sudo -n iptables "$@" 2>/dev/null
    else
        return 1
    fi
}

emit 'MODE' 'READ_ONLY_AGGREGATE'
emit 'OBSERVED_UTC' "$(date -u '+%Y-%m-%dT%H:%M:%SZ')"
emit 'PRIVATE_KEYS_READ' 'False'
emit 'WG_CONFIG_FILE_READ' 'False'
emit 'NETWORK_MUTATIONS_PERFORMED' 'False'
emit 'CLOUD_FIREWALL_EGRESS' 'NOT_CHECKED_VM_CANNOT_ATTEST_CLOUD_RULES'

if has systemctl; then
    unit_state wg-quick@wg0.service WG_SERVICE
    unit_state conan-wg-dns.service DNS_SERVICE
    unit_state conan-wg-udp443.service UDP443_COMPAT_SERVICE
    unit_state wg-traffic-collect.timer TRAFFIC_TIMER
else
    emit 'SYSTEMCTL' 'UNAVAILABLE'
fi
if has sysctl;then
    value="$(sysctl -n net.ipv4.ip_forward 2>/dev/null)" || value='UNKNOWN'
    case "$value" in 0|1)emit 'IP_FORWARD' "$value";; *)emit 'IP_FORWARD' 'UNKNOWN';;esac
else
    emit 'IP_FORWARD' 'UNKNOWN'
fi
if has wg;then
    listen="$(wg_read listen-port)" || listen=""
    case "$listen" in
       ''|*[!0-9]*)emit 'WG_LISTEN_PORT' 'UNAVAILABLE';;
       *) emit 'WG_LISTEN_PORT' "$listen";;
    esac
    latest="$(wg_read latest-handshakes)" || latest=""
    if [ -n "$latest" ];then
       # Input columns: private peer identifier, unix timestamp.
       # Never emit identifiers. The count is only an aggregate.
       now="$(date +%s)"
       printf '%s\n' "$latest" | awk -v now="$now" \
           'NF>=2 {n++;if($2>0){seen++;if(now-$2<=600 && now>=$2){fresh++}}}
            END{printf "P1M_GCP_PEER_ROWS=%d\nP1M_GCP_PEERS_WITH_HANDSHAKE=%d\nP1M_GCP_PEERS_FRESH_10MIN=%d\n",n,seen,fresh}'
    else
       emit 'WG_PEER_HANDSHAKE_SUMMARY' 'UNAVAILABLE_OR_NONE'
    fi
    transfer="$(wg_read transfer)" || transfer=""
    if [ -n "$transfer" ];then
       printf '%s\n' "$transfer" | awk 'NF>=3 {n++;rx+=$2;tx+=$3}
           END{printf "P1M_GCP_TRANSFER_PEER_COUNT=%d\nP1M_GCP_TRANSFER_RX_TOTAL_BYTES=%.0f\nP1M_GCP_TRANSFER_TX_TOTAL_BYTES=%.0f\n",n,rx,tx}'
    else
       emit 'WG_TRANSFER_SUMMARY' 'UNAVAILABLE_OR_NONE'
    fi
else
    emit 'WG_CMD' 'UNAVAILABLE'
fi
if has ss;then
    sockets="$(ss -H -lun 2>/dev/null)" || sockets=""
    # A local UDP/443 listener is not required when iptables redirects to 51820.
    if [ -n "$sockets" ];then
       printf '%s\n' "$sockets" | awk '
          /:51820([[:space:]]|$)/ {wg++}
          /:443([[:space:]]|$)/ {compat++}
          /10[.]66[.]66[.]1:53([[:space:]]|$)/ {dns++}
          END{
             printf "P1M_GCP_UDP51820_BINDING_ROWS=%d\n",wg
             printf "P1M_GCP_UDP443_BINDING_ROWS=%d\n",compat
             printf "P1M_GCP_PRIVATE_DNS_UDP53_BINDING_ROWS=%d\n",dns
          }'
    else
       emit 'UDP_SOCKET_QUERY' 'UNAVAILABLE_OR_EMPTY'
    fi
else
    emit 'SS_CMD' 'UNAVAILABLE'
fi
if has iptables;then
    prerouting="$(iptables_read -t nat -S PREROUTING)" || prerouting=""
    postrouting="$(iptables_read -t nat -S POSTROUTING)" || postrouting=""
    forward="$(iptables_read -S FORWARD)" || forward=""
    if [ -n "$prerouting" ];then
      printf '%s\n' "$prerouting" |
          awk '/--dport 443/ && /REDIRECT/ && /51820/ {count++}
              END{printf "P1M_GCP_UDP443_REDIRECT_RULE_COUNT=%d\n",count}'
    else
      emit 'UDP443_REDIRECT_RULE_COUNT' 'UNAVAILABLE'
    fi
    if [ -n "$postrouting" ];then
      printf '%s\n' "$postrouting" |
          awk '/MASQUERADE/ {n++}END{printf "P1M_GCP_POSTROUTING_MASQUERADE_RULE_COUNT=%d\n",n}'
    else
      emit 'POSTROUTING_MASQUERADE_RULE_COUNT' 'UNAVAILABLE'
    fi
    if [ -n "$forward" ];then
      emit 'FORWARD_CHAIN_INSPECTABLE' 'True'
    else
      emit 'FORWARD_CHAIN_INSPECTABLE' 'False'
    fi
else
    emit 'IPTABLES_CMD' 'UNAVAILABLE'
fi
# Script cannot establish cloud security groups/firewall policy, or whether
# real clients can complete a fresh handshake, DNS query, GCP egress/NAT.
emit 'END_TO_END_CONNECTIVITY_VERIFIED' 'False'
emit 'RESULT' 'READ_ONLY_INVENTORY_ONLY_NOT_LIVE_PROOF'
